import time

def best_time(f, repeats=5):
    times = []
    for _ in range(repeats):
        t0 = time.perf_counter()
        f()
        times.append(time.perf_counter() - t0)
    return min(times)

t_sum = best_time(lambda: sum(range(1_000_000)))
print(f"{t_sum:.4f} с")

from time import perf_counter as now

def best_time(f, repeats=5):
    times = []
    for _ in range(repeats):
        t0 = now()
        f()
        times.append(now() - t0)
    return min(times)

t_sum = best_time(lambda: sum(range(1_000_000)))
print(f"{t_sum:.4f} с")
